<?php require_once __DIR__.'/app/lib/Security.php';Security::start();$u=Security::requireRole(['admin','super_admin']);?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Users & Roles · TechSelectAI</title><style>body{font-family:Inter,system-ui,sans-serif;background:#f6f8fb;color:#172033;margin:0}main{max-width:1200px;margin:auto;padding:28px}.filters,.actions{display:flex;gap:10px;flex-wrap:wrap}.filters{margin:18px 0}input,select,button{padding:9px;border:1px solid #cbd5e1;border-radius:8px;background:#fff}button{background:#173b63;color:#fff;border:0;cursor:pointer}table{width:100%;border-collapse:collapse;background:#fff}th,td{padding:10px;border-bottom:1px solid #e8edf3;text-align:left}.muted{color:#64748b;font-size:12px}.matrix{margin-top:28px;overflow:auto}@media(max-width:720px){main{padding:16px}table{display:block;overflow:auto}}</style></head><body><main><h1>Users & Roles</h1><p class="muted">Server-side authorization remains the security boundary. Role visibility in this UI does not grant permission.</p><div class="filters"><input id="q" placeholder="Search name/email"><select id="role"><option value="">All roles</option><option>user</option><option>reviewer</option><option>data_editor</option><option>admin</option><option>super_admin</option></select><select id="status"><option value="">All status</option><option>pending</option><option>active</option><option>suspended</option><option>disabled</option></select><button onclick="load()">Filter</button></div><table><thead><tr><th>User</th><th>Role</th><th>Status</th><th>Last login</th><th></th></tr></thead><tbody id="rows"></tbody></table><section class="matrix"><h2>Permission matrix</h2><table><thead><tr><th>Action</th><th>Reviewer</th><th>Data editor</th><th>Admin</th><th>Super admin</th></tr></thead><tbody id="matrix"></tbody></table></section></main><script>let csrf='';function e(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}async function api(url,opt={}){opt.headers={...(opt.headers||{}),'Content-Type':'application/json','X-CSRF-Token':csrf};let r=await fetch(url,opt),d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'Request failed');return d}async function load(){let p=new URLSearchParams();['q','role','status'].forEach(id=>{let v=document.getElementById(id).value;if(v)p.set(id,v)});let d=await api('/api/admin-governance/users?'+p);csrf=d.csrf_token;rows.innerHTML=d.users.map(x=>`<tr><td><strong>${e(x.full_name)}</strong><br><span class="muted">${e(x.email)}</span></td><td><select id="r${x.id}">${['user','reviewer','data_editor','admin','super_admin'].map(r=>`<option ${r===x.role?'selected':''}>${r}</option>`).join('')}</select></td><td><select id="s${x.id}">${d.statuses.map(s=>`<option ${s===x.status?'selected':''}>${s}</option>`).join('')}</select></td><td>${e(x.last_login_at||'—')}</td><td><button onclick="save(${x.id})">Save</button></td></tr>`).join('');matrix.innerHTML=Object.entries(d.permissions).map(([k,v])=>`<tr><td>${e(k.replaceAll('_',' '))}</td>${['reviewer','data_editor','admin','super_admin'].map(r=>`<td>${v[r]?'✓':'—'}</td>`).join('')}</tr>`).join('')}async function save(id){try{await api('/api/admin-governance/users/'+id,{method:'PATCH',body:JSON.stringify({role:document.getElementById('r'+id).value,status:document.getElementById('s'+id).value})});await load();alert('Updated')}catch(err){alert(err.message)}}load();</script></body></html>